const usd=n=>Number.isFinite(n)?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n):'Add an amount';
const more=(body,label='More info')=>`<details class="more-info"><summary>${label}</summary><div>${body}</div></details>`;
const link=(route,label,secondary=false)=>`<a class="button ${secondary?'secondary':''}" href="#/${route}">${label}</a>`;
const action=(name,label,attrs='')=>`<button class="button" data-action="${name}" ${attrs}>${label}</button>`;
const nav=(back,next,label='Continue →',disabled=false)=>`<div class="guide-actions">${link(back,'← Back',true)}${next?link(next,label):action('guide-next',label,disabled?'disabled':'')}</div>`;
const reflectionSupport=state=>explorationSnapshot(state).lowConfidence?'<aside class="exploration-support"><strong>New to it? Start small.</strong><p>Confidence can grow with practice. It doesn’t lower your interest connections or close a career door.</p></aside>':'';
const reflectionNotice=state=>{const s=explorationSnapshot(state);return `<section class="exploration-notice"><h2>${h(s.title)}</h2><p>${h(s.copy)}</p>${reflectionSupport(state)}</section>`;};
const heading=(eyebrow,title,copy='')=>`<div class="page-intro guide-intro"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1>${copy?`<p class="intro-copy">${copy}</p>`:''}</div></div>`;
export function guideHome(state){const g=state.guide,hasDraft=g?.entry&&g.lastRoute,complete=g?.completed&&g.planMode!=='exploration',resume=g?.planMode==='exploration'?'guide/paths':g?.lastRoute;return `${heading('YOUR NEXT CHAPTER','A future you can picture.','One step at a time. One plan that’s yours.')}<section class="guided-hero"><div><span class="overline">THE FULL GUIDED JOURNEY</span><h2>Start with yourself.<br>Finish with a plan.</h2><p>Interests. Strengths. Careers. Preparation. Life in Austin.</p>${action('guide-start','Guide me from the beginning →','data-id="assessment"')}</div><svg viewBox="0 0 260 220" aria-hidden="true"><path d="M28 183C80 190 68 128 117 128S160 48 229 45" fill="none" stroke="#93a878" stroke-width="3" stroke-dasharray="6 8"/><g fill="#faf9ec" stroke="#66825c" stroke-width="2"><circle cx="29" cy="183" r="16"/><circle cx="117" cy="128" r="24"/><circle cx="229" cy="45" r="20"/></g><path d="m102 127 11 11 22-24m80-69 10 10 18-20" stroke="#426940" stroke-width="3" fill="none"/><path d="m62 46 5-15 5 15 15 5-15 5-5 15-5-15-15-5Z" fill="#dcb899"/><circle cx="200" cy="164" r="32" fill="#d9e7b9"/></svg></section>${hasDraft?`<section class="guide-resume"><div><strong>${complete?'Your personal plan is ready.':'Your progress is saved.'}</strong><p>${complete?'Keep refining it as you learn.':'Pick up at the next step.'}</p></div>${link(complete?'plan':resume,complete?'Open My Plan →':'Resume →')}</section>`:''}<div class="section-title"><h2>Or start with a question.</h2></div><div class="guide-entry-grid">${entryPoints.slice(1).map((e,i)=>`<button class="guide-entry tone-${i}" data-action="guide-start" data-id="${e.id}"><span class="entry-symbol" aria-hidden="true">${e.symbol}</span><h3>${e.title}</h3><p>${e.copy}</p><span class="entry-arrow" aria-hidden="true">→</span></button>`).join('')}</div><p class="guide-home-note">Every starting point leads to the same personal plan.</p>`;}
export function guideProgress(state,step){const n=flowSteps.findIndex(([key])=>key===step);return `<div class="guide-progress"><span>${h(entryPoints.find(e=>e.id===state.guide.entry)?.title||'Your personal guide')}</span><strong>${n>=0?`${flowSteps[n][1]}`:'Your starting point'}</strong><div class="guide-progress-track" aria-hidden="true">${flowSteps.map(([,],i)=>`<i class="${i<=n?'done':''}"></i>`).join('')}</div></div>`;}
export function assessmentBanner(state){return `<div class="assessment-guide-bar"><strong>Your answers save as you go.</strong><a href="#/guide/assessment">Save & return to the guide</a></div>`;}
export function guidePage(route,state){const g=state.guide,part=route.split('/')[1]||'paths',o=occupationById(g.primaryCareer);let body='';
 if(part==='assessment'){
 const next=modules.find(m=>!isComplete(state,m.id));body=`${heading('THE FULL GUIDED JOURNEY','Let’s get to know you.','Five short sections. Your answers save as you go.')}<div class="assessment-map">${modules.map((m,i)=>`<div class="${isComplete(state,m.id)?'complete':''}"><span>${isComplete(state,m.id)?'✓':i+1}</span><div><h3>${h(m.title)}</h3><p>${h(m.time)}</p></div></div>`).join('')}</div><p>Start with what you enjoy. Your picture can change as you try new things.</p>${nav('overview',next?`activity/${next.id}`:'guide/assessment-results',next?'Continue my journey →':'See my starting picture →')}`;
 }else if(part==='assessment-results'){
 body=`${heading('YOUR PICTURE SO FAR','You have a starting point.','Now connect what you’ve learned with possible work.')}<div class="guide-fact-grid"><article><b>${completedCount(state)} / 5</b><p>sections visited</p></article><article><b>${state.priorities.length}</b><p>priorities chosen</p></article></div>${state.priorities.length?`<div class="tags">${state.priorities.map(id=>`<span class="tag">${h(priorities.find(x=>x.id===id)?.title)}</span>`).join('')}</div>`:''}${reflectionNotice(state)}${more(`<p>Already have an O*NET or ability report? Add its original results here.</p>${link('results','Add existing results →',true)}<p>External results are optional. You can continue with your reflections and experiences.</p>`,'Add an existing assessment · optional')}${nav('guide/assessment','guide/paths','Find possible paths →')}`;
 }else if(part==='lifestyle'){
 return lifestyleBuilderPage(state);
 }else if(part==='lifestyle-summary'){
 return lifestyleSummaryPage(state);
 }else if(part==='income-goal'){
 body=`${heading('INCOME EXPECTATIONS','What income would you like to work toward?','Yearly pay before tax. You can change this goal.')}<section class="guide-input-panel"><label for="guide-income-target">Annual income goal</label><div class="guide-money-input"><span>$</span><input id="guide-income-target" data-guide-field="incomeTarget" type="number" min="1000" max="1000000" step="1000" value="${h(g.incomeTarget)}" placeholder="60000"></div><div class="income-presets">${[40000,60000,80000,100000,150000].map(v=>`<button data-action="guide-income-preset" data-id="${v}">${formatSalary(v)}</button>`).join('')}</div><p>Tap an amount to see careers. Or enter your own.</p><p id="guide-income-error" class="field-help">Choose $1,000–$1,000,000 per year.</p></section>${nav('overview',null,'Explore possible paths →',!(Number(g.incomeTarget)>=1000&&Number(g.incomeTarget)<=1000000))}`;
 }else if(part==='paths'){
 const recommendations=suggestedPaths(state),picture=interestPicture(state),highlighted=new Set(availableFamilies(state).filter(f=>f.connection.supported).slice(0,3).map(f=>f.id));body=`${heading(g.entry==='training'?'CAREER PATHS WITHOUT COLLEGE':g.entry==='college'?'CAREER PATHS WITH COLLEGE':'START BROAD','What kind of work draws you in?','Choose up to three interests. Keep your options open.')}${reflectionSupport(state)}<a class="tree-entry-link" href="#/career-tree">See the complete career tree →</a><div class="guide-path-grid">${availableFamilies(state).map(f=>`<button class="guide-choice ${selectedFamilies(g).includes(f.id)?'selected':''}" data-action="guide-family" data-id="${f.id}" aria-pressed="${selectedFamilies(g).includes(f.id)}"><span class="entry-symbol" aria-hidden="true">${f.symbol}</span><h2>${h(f.title)}</h2><p>${h(f.copy)}</p>${g.entry==='assessment'&&highlighted.has(f.id)?'<span class="guide-evidence-tag">Worth exploring</span>':''}</button>`).join('')}</div>${g.entry==='assessment'?more('<p>Our 30 original prompts explore what you enjoy. They are not the O*NET Interest Profiler or an aptitude test. Broad fields come first; your chosen day-to-day tasks bring careers forward. Blank and unfamiliar answers stay unknown. Flat interests do not produce a winner.</p><p><a href="https://www.careeronestop.org/Toolkit/Careers/interest-assessment.aspx" target="_blank" rel="noopener noreferrer">Try the official interest assessment ↗</a></p>'+directions.filter(d=>recommendations.includes(d.id)).map(d=>'<p><strong>'+h(d.title)+'</strong>: '+h(reflectionReasons(state,d.id)[0]||'An entered interest theme, experience, or saved choice connects with this path.')+'</p>').join(''),'Why some paths connect'):''}${guideGoal(state)}<p class="selection-count" role="status">${selectedFamilies(g).length} of 3 interests selected</p>${nav(g.entry==='assessment'?'guide/assessment-results':g.entry==='income'?'guide/income-goal':g.entry==='lifestyle'?'guide/lifestyle':'overview',null,'Explore these interests →',!selectedFamilies(g).length)}`;
 }else if(part==='specialty'){
 body=`${heading('NARROW THE PATH','Which areas interest you?','Choose up to three. Careers from all your choices appear next.')}<div class="guide-path-grid">${specialtyOptions(state).map(d=>`<button class="guide-choice ${selectedPaths(g).includes(d.id)?'selected':''}" data-action="guide-path" data-id="${d.id}" aria-pressed="${selectedPaths(g).includes(d.id)}"><h2>${h(d.title)}</h2><p>${h(d.description)}</p></button>`).join('')}</div><p class="selection-count" role="status">${selectedPaths(g).length} of 3 areas selected</p>${specialtyOptions(state).length?'':link('guide/paths','Choose an interest →')}${nav('guide/paths',null,'See careers →',!selectedPaths(g).length)}`;
 }else if(part==='work-fit'){
 if(!selectedPaths(g).length)return heading('YOUR GUIDE','Choose a field to explore first.')+link('guide/paths','Choose a field →');
 const choices=taskChoicesFor(careerOptions({...state,guide:{...g,taskInterests:[]}}),selectedPaths(g)),button=t=>`<button class="guide-choice task-choice ${g.taskInterests.includes(t.id)?'selected':''}" data-action="guide-task" data-id="${h(t.id)}" aria-pressed="${g.taskInterests.includes(t.id)}"><span aria-hidden="true">${g.taskInterests.includes(t.id)?'✓':'+'}</span><strong>${h(t.text)}</strong></button>`;
 body=`${heading('GET A FEEL FOR THE WORK','Which parts would you enjoy?','Pick a few. It’s fine to be unsure.')}<div class="task-choice-grid">${choices.slice(0,12).map(button).join('')}</div>${choices.length>12?more('<div class="task-choice-grid">'+choices.slice(12).map(button).join('')+'</div>','More kinds of work'):''}<p>These choices help bring relevant careers forward. Every career stays available.</p>${nav(specialtyOptions(state).length===1?'guide/paths':'guide/specialty','guide/careers',g.taskInterests.length?'See careers for these tasks →':'I’m not sure yet · show careers →')}`;
 }else if(part==='careers'){
 const opts=selectedPaths(g).length?careerOptions(state):[];body=`${heading('SPECIFIC CAREERS','Find work you want to try.','Your chosen tasks come first. Tap a career to explore it.')}${reflectionSupport(state)}${guideGoal(state)}<div class="tags">${selectedPaths(g).map(id=>`<span class="tag">${h(directions.find(d=>d.id===id)?.title)}</span>`).join('')}</div><div class="guide-career-grid">${opts.map(c=>{const target=g.incomeTarget&&['income','lifestyle'].includes(g.entry),match=target?goalMatch(c,g.incomeTarget):null,pay=salaryProgression(c.id);return `<article class="guide-choice career-choice"><button class="career-open" data-action="guide-candidate" data-id="${c.id}"><h2>${h(c.finance?.title||c.title)}</h2><p>${h(c.finance?.requirements.typicalEntry||c.preparation.typicalEducation.join(' or '))}</p><span>Understand this career →</span></button>${matchNote(state,c)}<b class="guide-entry-pay">${formatSalary(salaryAtStage(c.id))}</b><span>Entry level / year · ${h(salaryEvidenceLabel(pay?.stages[0]))}</span>${pay?.entryContext?'<p class="salary-scope-note"><strong>Usually after related experience.</strong></p>':''}${pay?.sharedWageScope?'<p class="salary-scope-note">'+h(pay.sharedWageScope)+'</p>':''}${pay?.variableHours?'<p class="salary-scope-note">Full-time equivalent; paid hours vary.</p>':''}${salaryLifestyleLink(c.id,'entry','careers')}${lifestyleFitCard(state,c.id)}${target&&!g.lifestylePreset?`<p class="guide-goal-match">${match?`Your goal: ${match.years===0?'entry-level scenario':match.years+'-year pay illustration'}`:'This model stays below your income goal.'}</p>`:''}</article>`;}).join('')}</div>${opts.length?'':`<p>Choose an interest to see careers.</p>${link('guide/paths','Choose interests →')}`} <div class="guide-actions">${link('guide/work-fit','← Back',true)}</div>`;
 }else if(part==='career')return simpleCareerPage(route.split('/')[2],state,true);
 else if(!o)return `${heading('YOUR GUIDE','Choose a career first.','Your other answers are saved.')}${link('guide/paths','Choose a path →')}`;
 else if(part==='education'){
 const t=texasRequirements[o.id],routes=o.finance?.educationRoutes.routes||o.preparation.typicalEducation;
 body=`${heading('PLAN YOUR PREPARATION',h(careerTitle(o)),'The education and training behind the work.')}<section class="guide-input-panel"><h2>${h(careerEducationSummary(o))}</h2><ul>${careerEducationBullets(o).map(x=>`<li>${h(x)}</li>`).join('')}</ul>${routes.length>1?`<h3>Choose a study or training focus.</h3><div class="preparation-choices">${routes.map(x=>`<button data-action="guide-preparation" data-value="${h(x)}">${h(x)} <span aria-hidden="true">→</span></button>`).join('')}</div>`:`<p><strong>${h(routes[0]||t?.typicalEntry||'Build relevant experience.')}</strong></p>`}${collegeBenefitPanel(o)}${t?more(`<p>${h(t.detail)}</p><p>${t.sourceURLs.map((url,i)=>`<a href="${h(url)}" target="_blank" rel="noopener">Texas source ${i+1} ↗</a>`).join(' · ')}</p>`):more('<p>Psychiatric aides provide supervised support. Psychiatric technicians have distinct preparation and duties. Clinical psychologists require doctoral preparation and Texas professional licensing. A general psychology degree alone does not authorize clinical practice.</p><a href="https://bhec.texas.gov/texas-state-board-of-examiners-of-psychologists/" target="_blank" rel="noopener">Texas psychology board ↗</a>')}</section>${collegeProgramPanel(state,o.id,{selectable:true})}${trainingCostPreview(o.id)}${clinicalTrainingTimeline(o.id)}${needsFurtherStudy(o.id)?professionalCostPanel(o.id):''}${more(educationCostsPanel(state,o.id),'College costs & ways to pay')}${more(`${link('money','Add or update my education budget →',true)}<p>Saved budgets appear in My Plan. Return here to continue.</p>`,'Add a personal cost estimate · optional')}<div class="guide-actions">${link('guide/career/'+o.id,'← Back',true)}${routes.length===1?action('guide-preparation',g.salaryPicked?'Make My Plan →':'See pay & lifestyle →',`data-value="${h(routes[0])}"`):''}</div>`;
 }else if(part==='income'){
 body=`${heading('INCOME OVER TIME',h(careerTitle(o)),o.id==='physician'?'Start with paid residency. Practice pay comes later.':'Start with entry-level pay. Explore later stages.')} ${salaryPanel(o.id,{stage:g.salaryStage,from:'income'})}<p>Tap a salary to picture life in Austin.</p><div class="guide-actions">${link('guide/education','← Back',true)}${g.salaryStage==='custom'?link('guide/life','Keep my custom income →'):''}</div>`;
 }else if(part==='life'){
 body=`${heading('PICTURE YOUR LIFE',h(careerTitle(o)),'What would you keep? What would you change?')}<div class="guide-lifestyle-embed">${lifestylePage(state)}</div><div class="guide-actions">${link('guide/income','← Back',true)}${action('guide-create-plan','Keep this picture & make My Plan →')}</div>`;
 }else if(part==='next'){
 body=`${heading('MAKE IT PRACTICAL','Three steps to move forward.','Your plan will include these small starting actions.')}<details class="more-info"><summary>What goes into my plan?</summary><div class="guide-next-list"><article><span>01</span><h2>Try one part of the work.</h2><p>A safe class project, demonstration, or introductory lesson.</p></article><article><span>02</span><h2>Map the preparation.</h2><p>One program or provider. Its requirements, cost, and aid.</p></article><article><span>03</span><h2>Talk with someone doing it.</h2><p>A normal day. A first job. What changes with experience.</p></article></div></details><p>You can edit these steps and add dates in My Plan.</p>${nav('guide/life',null,'Create My Plan →')}`;
 }else return `${heading('YOUR GUIDE','Let’s pick up the next step.')}${link('guide/paths','Continue →')}`;
 return `${guideProgress(state,['specialty','careers'].includes(part)?'paths':part)}${body}`;
}
export function simpleCareerPage(id,state,guided=false,{journey=false,reasons=[],differentClues=false}={}){if(occupationById(id))return resultCareerPage(state,id);const o=occupationById(id);if(!o)return `${heading('CAREER','Choose a career from a path.')}${link('guide/paths','Choose a path →')}`;const c=o.finance,t=texasRequirements[id];return `<div class="career-detail-page">${guided&&!journey?guideProgress(state,'career'):''}${heading('UNDERSTAND THE WORK',h(careerTitle(o)),'Could you picture yourself doing this?')}${educationBadges(o)}${differentClues?'<p class="insight-tradeoff">Some earlier answers point to other work. Try this job’s tasks before choosing.</p>':''}${reasons.length?more('<ul>'+reasons.map(t=>'<li>'+h(t)+'</li>').join('')+'</ul>','More info · why this job'):''}<nav class="career-section-nav" aria-label="Job details">${journey?'<a href="#/journey/professions">← Matches</a>':''}${[['career-work','Work'],['career-education','Training'],['career-pay','Pay']].map(([anchor,label])=>'<a href="#'+anchor+'" data-scroll-to="'+anchor+'">'+label+'</a>').join('')}</nav>${journey?action('journey-plan',state.guide.primaryCareer===id?'Open my plan →':'Choose this job →',`data-id="${h(id)}" data-mobile-primary`):''}${reflectionSupport(state)}<section class="guide-work-panel" id="career-work"><span class="overline">WHAT YOU COULD DO</span><h2>Picture a working day.</h2><ul>${(careerLanguage[id]||['Explore the work with a class project or conversation.']).map(task=>`<li>${h(task)}</li>`).join('')}</ul>${more(`<p>${h(o.summary)}</p><p>${o.tasks.map(task=>h(task.text)).join(' ')}</p><p>${[...new Set((o.sources||[]).map(s=>s.url))].slice(0,3).map(u=>`<a href="${h(u)}" target="_blank" rel="noopener">Occupation source ↗</a>`).join(' · ')}</p>`,'More about the work')}</section>${careerInsightsPanel(state,o)}${more(occupationProfilePanels(o,state),'Skills, qualities & working life')}${clinicalTrainingTimeline(id)}${lifestyleFitCard(state,id,guided?'guided-career':'career')}${opportunitiesPanel(state,{anchorId:id,compact:true})}${salaryPanel(id,{from:guided?'guided-career':'career'})}<section class="guide-input-panel" id="career-education"><span class="overline">EDUCATION & TRAINING</span><h2>${h(careerEducationSummary(o))}</h2><ul>${careerEducationBullets(o).slice(0,3).map(x=>'<li>'+h(x)+'</li>').join('')}</ul>${collegeBenefitPanel(o)}${more(`<p>${h(t?.detail||c?.requirements.training||'Education and legal authority are separate. The next step explains preparation for this specific role.')}</p><p>${(t?.sourceURLs||[o.url]).map(u=>`<a href="${h(u)}" target="_blank" rel="noopener">Requirements source ↗</a>`).join(' · ')}</p>`)}</section>${collegeProgramPanel(state,id,{selectable:guided})}${trainingCostPreview(id)}${careerFundingPanel(state,id)}${more(educationCostsPanel(state,id),'Education costs & aid')}<div class="guide-actions">${journey?link('journey/professions','← Job matches',true):link(guided?state.guide.careerBack||'guide/careers':'overview','← Back',true)+action('guide-use-career',guided?'Continue to preparation →':'Build my plan with this career →',`data-id="${h(id)}"`)}</div>${state.guide?.primaryCareer&&state.guide.primaryCareer!==id?`<button class="text-link" data-action="guide-save-alternative" data-id="${h(id)}">Keep as an alternative +</button>`:''}</div>`;}
export function personalPlanPage(state){if(occupationById(state.guide?.primaryCareer)?.expandedDegree)return expandedPersonalPlan(state);if(state.guide?.planMode==='exploration')return guidePage('guide/paths',state);if(!occupationById(state.guide?.primaryCareer))return `${heading('MY PLAN','Your plan starts with one possibility.','Choose a starting point. We’ll guide you from there.')}${link('overview','Start my plan →')}${state.actions.length?more(state.actions.map(a=>`<p><strong>${h(a.title)}</strong></p>${a.notice?'<p>'+h(a.notice)+'</p>':''}`).join(''),'My earlier next steps'):''}`;return resultsPlanPage(state,{historyHTML:explorationHistoryPanel(state)});}

function earlierCareerSteps(actions){if(!actions.length)return '';const groups=new Map();for(const a of actions){const id=a.careerId||'';if(!groups.has(id))groups.set(id,[]);groups.get(id).push(a);}return more([...groups].map(([id,rows])=>'<section><h3>'+h(id?(occupationById(id)?.finance?.title||occupationById(id)?.title||'Earlier career'):'My other steps')+'</h3>'+rows.map(planAction).join('')+'</section>').join(''),'Earlier career steps & other saved work');}

function planEducationBudgets(state,o){const assigned=state.finance.plans.filter(p=>p.entityLinks.includes(o.id)),other=state.finance.plans.filter(p=>!p.entityLinks.includes(o.id));const card=plan=>{const c=calculateCollege(plan);return `<article><h3>${h(plan.institution||'My education budget')}</h3><p>${h(plan.program||'Program not entered')}</p><b>${usd(c.netPrice)}</b><p>Cost after grants · ${h(plan.year)} · ${h(plan.period.replaceAll('_',' '))}</p></article>`;};return `<div class="plan-costs"><p><strong>${assigned.length?'Budgets linked to this career':needsFurtherStudy(o.id)?'College only · before aid':isTraining(o)?'Optional college references · before aid':'College cost references · before aid'}</strong></p>${assigned.length?assigned.map(card).join(''):'<p>UT Austin resident tuition: $10,858–$13,576 / academic year.<br>ACC in-district tuition & fees: $2,550 / 30-credit academic year.</p>'}</div>${other.length?more('<p>Kept from your earlier work. These budgets are not assigned to '+h(careerTitle(o))+'.</p>'+other.map(card).join('')+link('money','Review saved budgets →',true),'Other saved education budgets'):''}`;}

const activityFeedback=a=>a.done?`<div class="activity-feedback"><p>After trying it, how do you feel?</p><div role="group" aria-label="Interest after this activity">${[['more','More interested'],['less','Less interested'],['curious','Still curious']].map(([value,label])=>`<button data-action="activity-feedback" data-id="${h(a.id)}" data-value="${value}" aria-pressed="${a.interestFeedback===value}">${label}</button>`).join('')}</div></div>`:'';
const shortStep=text=>{const first=String(text||'').match(/^.*?[.!?](?:\s|$)/)?.[0]?.trim()||String(text||'');return first.split(/\s+/).length<=25?first:first.split(/\s+/).slice(0,25).join(' ')+'…';};
const planAction=a=>`<article class="personal-action"><label><input type="checkbox" data-action-check="${h(a.id)}" ${a.done?'checked':''}><strong>${h(a.title)}</strong></label><p>${h(shortStep(a.detail))}</p>${activityFeedback(a)}${more('<p>'+h(a.detail)+'</p><div class="field"><label for="plan-date-'+h(a.id)+'">Target date · optional</label><input id="plan-date-'+h(a.id)+'" type="date" data-plan-action="'+h(a.id)+'" data-plan-field="dueDate" value="'+h(a.dueDate||'')+'"></div><label for="plan-detail-'+h(a.id)+'">What I will do</label><textarea id="plan-detail-'+h(a.id)+'" data-personal-action="'+h(a.id)+'" maxlength="2000">'+h(a.detail)+'</textarea>','More info · details, date and edits')}${more(planNotes(a),'My notes'+(a.notice?' · saved':''))}</article>`;

function planInterests(state){const paths=selectedPaths(state.guide);return paths.length?`<p><strong>My interests</strong></p><div class="tags">${paths.map(id=>`<span class="tag">${h(directions.find(d=>d.id===id)?.title)}</span>`).join('')}</div>${state.guide.taskInterests.length?'<p><strong>Parts of work I want to try</strong></p><div class="tags">'+state.guide.taskInterests.map(t=>'<span class="tag">'+h(taskPrompts[t]||t)+'</span>').join('')+'</div>':''}`:'';}
function guideGoal(state){const g=state.guide;if(g.lifestylePreset){const range=lifestyleIncomeRange(state.finance.lifestyle);return `<aside class="guide-goal-strip">${g.entry==='income'&&g.incomeTarget?`<strong>Your income goal: ${formatSalary(Number(g.incomeTarget))} / year</strong>`:''}<strong>Your Austin lifestyle${range?' · '+formatSalary(range.low)+'–'+formatSalary(range.high)+' / year':''}</strong><span>${({shared:'A shared start',alone:'A place of your own',comfort:'More room for extras',custom:'A mix of the choices that matter to you'})[g.lifestylePreset]}</span><a href="#/guide/lifestyle-summary">Review my lifestyle preferences →</a></aside>`;}if(g.entry!=='income'||!g.incomeTarget)return '';return `<aside class="guide-goal-strip"><strong>Your income goal: ${formatSalary(Number(g.incomeTarget))} / year</strong><span>Before tax</span></aside>`;}
function lifestyleFitCard(state,id,from='careers'){const fit=careerLifestyleFit(state,id);if(!fit)return '';return `<aside class="career-lifestyle-fit fit-${fit.key}"><span class="overline">YOUR LIFESTYLE · BUDGET COMPARISON</span><strong>${h(fit.title)}</strong><p>${h(fit.copy)}</p>${trainingFundingNote(state,id)}<a href="#/salary/${h(id)}/${fit.stage}?from=${from}">See the budget →</a>${more('<p>This compares your chosen spending picture with four modeled pay stages after estimated taxes, retirement, and health costs. This is conditional on earning the pay shown; it is not a measured probability or a job guarantee. A close fit leaves less than 10% of take-home unallocated. College, income, and lifestyle never change your interests or ability evidence.</p>','How we compare')}</aside>`;}
export function salaryPreviewPage(id,stage,state,from='career'){
 from=['career','guided-career','income','plan','careers'].includes(from)?from:'career';
 const o=occupationById(id),p=salaryProgression(id),inputs=salaryPreviewInputs(state,id,stage);if(!o||!inputs||!salaryPreviewStages(id).some(s=>s.key===stage))return `${heading('LIFESTYLE PREVIEW','Let’s find a salary to explore.')}${link('guide/paths','Choose a career →')}`;
 const selected=salaryPreviewStages(id).find(s=>s.key===stage),back={career:'career/'+id,'guided-career':(state.profileJourney?.started?'journey/profession/':'guide/career/')+id,income:'guide/income',plan:'plan',careers:'guide/careers'}[from]||'career/'+id;
 const canKeep=state.guide.primaryCareer===id;
 return `<div class="salary-preview"><div class="guide-actions preview-back">${link(back,'← Back to '+(from==='plan'?'My Plan':from==='careers'?'careers':'job'),true)}</div>${heading('LIFE IN AUSTIN · ONE ADULT',`${formatSalary(selected.amount)} / year`,h(careerTitle(o))+' · '+h(selected.label)+' · '+h(salaryEvidenceLabel(selected)))}<p class="preview-note">Preview only. Your saved plan is unchanged.</p>${needsFurtherStudy(id)&&Number(inputs.debt)===0?'<p><strong>Before any student-loan payments.</strong></p>':''}${trainingFundingNote(state,id)}${lifestyleOutput(inputs).replace(/<button[^>]*data-action="life-adjust"[^>]*>[\s\S]*?<\/button>/g,'')}${more(`<nav class="salary-preview-stages" aria-label="Compare salary lifestyles">${salaryPreviewStages(id).map(s=>`<a href="#/salary/${id}/${s.key}?from=${from}" ${stage===s.key?'aria-current="page"':''}>${h(s.label)}<b>${formatSalary(s.amount)}</b></a>`).join('')}</nav>`,'More info · compare pay stages')}${lifestyleStressPanel(inputs)}${more(workScenarioPanel(state,id,inputs),'More info · change hours or work for myself')}<p>These are choices to picture, not promises about what you will own.</p><div class="guide-actions">${link(back,'← Back',true)}${action('guide-keep-salary',canKeep?(from==='plan'?'Use this salary in My Plan →':'Keep this picture in My Plan →'):'Explore this career →',`data-id="${id}" data-stage="${stage}" data-from="${from}"`)}</div>${more('<p>Employee or independent-work tax scenario in today’s dollars. Uses your chosen work arrangement and current spending assumptions and the selected salary, with retirement capped to the modeled employee limit. Personal take-home overrides are not used to compare salaries. Career pay is modeled unless an employer schedule is shown. Housing, meals, transport, and travel are budget choices, not promises of affordability.</p>','How this preview works')}</div>`;
}

function lifestyleBuilderPage(state){const b=state.guide.lifestyleBuilder,c=lifestyleChoices[b.step]||lifestyleChoices[0],options=c.id==='home'&&b.homeMode==='own'?c.ownOptions:c.options;return `<header class="question-intro"><h1>${h(c.question)}</h1>${b.step===0?'<p>Choose what feels right. We’ll add it up at the end.</p>':''}</header>${c.id==='home'?`<div class="builder-home-mode" role="group" aria-label="Home plans"><button data-action="builder-home-mode" data-id="rent" aria-pressed="${b.homeMode==='rent'}">Prefer to rent</button><button data-action="builder-home-mode" data-id="own" aria-pressed="${b.homeMode==='own'}">Prefer to own</button></div>`:''}<div class="builder-options" data-life-category="${c.id}">${options.map((o,i)=>`<button class="builder-option ${b.choices[c.id]===i?'selected':''}" data-action="builder-pick" data-id="${c.id}" data-value="${i}" aria-pressed="${b.choices[c.id]===i}"><span class="builder-symbol" aria-hidden="true">${lifestyleGlyph(c.id,i,b.homeMode)}</span><h2>${h(o.title)}</h2><p>${h(o.copy)}</p></button>`).join('')}</div><div class="guide-actions">${b.step?action('builder-back','← Back'):link('overview','← Back',true)}${b.complete?link('guide/lifestyle-summary','My saved picture →',true):''}</div>`;}
function lifestyleSummaryPage(state){const b=state.guide.lifestyleBuilder;if(!b.complete||!builderReady(b))return `${heading('YOUR LIFESTYLE','Let’s finish picturing your life.')}${link('guide/lifestyle','Keep choosing →')}`;const p=state.finance.lifestyle,tally=lifestyleTally(p,b),range=lifestyleIncomeRange(p);if(!tally||!range)return `${heading('YOUR LIFESTYLE','A few choices need another look.')}${link('guide/lifestyle','Review my choices →')}`;const essentials=new Set(['Phone & internet','Household & personal care','Health budget','Debt payments','Dependents / other essentials']),fixed=tally.rows.filter(r=>essentials.has(r.label)).reduce((n,r)=>n+r.display,0),rows=[...tally.rows.filter(r=>!essentials.has(r.label)),{label:'Everyday essentials',display:fixed}];return `<div class="lifestyle-summary">${heading('YOUR AUSTIN PICTURE','Here’s how your choices add up.','One adult. Monthly planning amounts, rounded to keep it simple.')}<section class="lifestyle-tally"><h2>Your monthly tally</h2><dl>${rows.map(r=>`<div><dt>${h(r.label)}</dt><dd>${usd(r.display)}</dd></div>`).join('')}</dl><div class="tally-total"><span>Your monthly total</span><strong>About ${usd(tally.total)}</strong></div><p>Includes cash savings and everyday essentials.</p></section><section class="picture-income-range"><span>Income needed for your choices</span><strong>${formatSalary(range.low)}–${formatSalary(range.high)} / year</strong><p>Before tax. The lower end covers your costs. The upper end adds a cushion.</p></section>${tally.result.carUpfront?`<p class="ownership-cash">The car also needs ${usd(tally.result.carUpfront)} down. This is separate from the monthly total.</p>`:''}${p.housingMode==='own'?`<p class="ownership-cash">Buying also needs about ${usd(Math.round(tally.result.upfront/1000)*1000)} upfront.</p>`+more(`<p>Owning also needs money upfront. This example uses a 20% down payment, closing costs, and an emergency reserve. The modeled upfront target is about ${usd(Math.round(tally.result.upfront/1000)*1000)}. A salary alone does not establish mortgage eligibility.</p>`,'A home also needs upfront savings'):''}<details class="more-info"><summary>Change a choice</summary><div class="builder-review-choices">${lifestyleChoices.map(c=>{const options=c.id==='home'&&p.housingMode==='own'?c.ownOptions:c.options;return `<button data-action="builder-edit" data-id="${c.id}"><span aria-hidden="true">${lifestyleGlyph(c.id,b.choices[c.id],b.homeMode)}</span><strong>${h(options[b.choices[c.id]].title)}</strong><span>Change →</span></button>`;}).join('')}</div></details>${more('<p>Everyday essentials cover phone, home supplies, health, and any saved debt or care costs. These are editable estimates, not price quotes. Home and car purchases also take upfront money. Phone, household, and health costs are included; existing debt and care needs are kept. The income range estimates 2026 employee taxes and retirement saving, then adds room to leave 20% of take-home unallocated at the upper end. It is a budget target range, not an income ceiling or a probability.</p><a href="#/source-review">Sources behind these estimates →</a>','More info · how we add it up')}<div class="guide-actions mobile-step-actions">${link('guide/lifestyle','← Back',true)}${link('guide/paths','Find careers for this life →')}</div></div>`;}


const observationFields=[['notice','What I noticed'],['enjoyed','What I enjoyed'],['difficult','What was difficult'],['learned','What I learned'],['surprising','What surprised me'],['support','Support I want']];
function planNotes(a,readOnly=false){return observationFields.filter(([key])=>key==='notice'||a[key]).map(([key,label])=>readOnly?(a[key]?`<p><strong>${label}</strong><br>${h(a[key])}</p>`:''):`<div class="field"><label for="plan-${key}-${h(a.id)}">${label}</label><textarea id="plan-${key}-${h(a.id)}" data-plan-action="${h(a.id)}" data-plan-field="${key}" maxlength="2000" placeholder="What held your interest? What would you try again?">${h(a[key]||'')}</textarea></div>`).join('')+(a.continueDecision?'<p><strong>My next thought:</strong> '+h(({continue:'Keep exploring',questions:'I have questions',later:'Maybe later'})[a.continueDecision]||a.continueDecision)+'</p>':'');}
export function explorationHistoryPanel(state,{readOnly=false}={}){
 const trail=explorationHistory(state);if(!trail)return '';
 const done=trail.actions.filter(a=>a.done).length,noted=trail.actions.filter(a=>observationFields.some(([key])=>a[key])||a.continueDecision).length;
 const earlierInterests=(trail.pathIds.length?'<h3>Earlier areas</h3><p>'+trail.pathIds.map(id=>h(directions.find(d=>d.id===id)?.title)).join(' · ')+'</p>':'')+(trail.taskInterests.length?'<h3>Work I wanted to try</h3>'+trail.taskInterests.map(id=>'<p>'+h(taskPrompts[id])+'</p>').join(''):'')+(trail.likedActivityIds.length?'<h3>Activities I liked earlier</h3>'+trail.likedActivityIds.map(id=>'<p>'+h(curiosity.find(q=>q.id===id)?.text)+'</p>').join(''):'')+(trail.priorityIds.length?'<h3>What mattered to me</h3><p>'+trail.priorityIds.map(id=>h(priorities.find(p=>p.id===id)?.title)).join(' · ')+'</p>':'');
 const activities=trail.actions.map(a=>readOnly?'<article class="personal-action"><h3>'+h(a.title)+'</h3><p><strong>'+(a.done?'Completed':'Still open')+'</strong>'+(a.dueDate?' · Target date: '+h(a.dueDate):'')+'</p><p>'+h(a.detail)+'</p>'+planNotes(a,true)+'</article>':planAction(a)).join('');
 return `<section class="personal-plan-section exploration-history"><span class="overline">MY EARLIER EXPLORATION</span><h2>What I’m bringing with me.</h2>${trail.actions.length?'<p>'+done+' completed '+(done===1?'activity':'activities')+' · '+noted+' '+(noted===1?'activity has':'activities have')+' notes</p>':''}${trail.familyIds.length?'<div class="tags">'+trail.familyIds.map(id=>'<span class="tag">'+h(careerFamilies.find(f=>f.id===id)?.title)+'</span>').join('')+'</div>':''}<p>Earlier interests stay part of your story as your focus changes.</p>${more(activities+(earlierInterests?more(earlierInterests,'Earlier interest details'):''),'Earlier activities, interests & notes')}</section>`;
}
